const express = require('express');
const knex = require('knex')({ client: 'pg', connection: process.env.DB_URL });

const app = express();
app.use(express.json({ limit: '10mb' }));

app.post('/api/wasm/execute-query', async (req, res) => {
  const { wasmBase64, targetVaultId } = req.body;

  // Verify that target vault is owned by the authenticated tenant
  const vault = await knex('secure_data_vaults')
    .where({ vault_id: targetVaultId, tenant_id: req.user.tenant_id })
    .first();
  if (!vault) {
    return res.status(404).json({ error: 'Target data vault not found' });
  }

  const wasmBuffer = Buffer.from(wasmBase64, 'base64');
  let outputResult = 0;

  const importObject = {
    env: {
      read_vault_record: async (keyOffset, keyLen) => {
        return vault.secret_numeric_metric;
      },
      write_result: (val) => { outputResult = val; }
    }
  };

  try {
    const compiledModule = await WebAssembly.instantiate(wasmBuffer, importObject);
    compiledModule.instance.exports.run_audit();
    return res.json({ targetVaultId, result: outputResult });
  } catch (err) {
    return res.status(500).json({ error: 'WASM module execution failed' });
  }
});

module.exports = app;
